script:
// IconButton (ds-metrics §2 — CircularIconButton): circle 44 (large) / 40 (small) with a 22 / 20 icon, tint el16,
// disabled el6. style: solid = bg1Elevated (≈ solidChromeSurface), glass = 20% ink tint (≈ glassButtonBackground,
// no blur), outline = el3 hairline, plain = no surface. The DS has no press visual here. Give the instance an
// a11y label — the button has no text.
param icon: icon
param size: "large" | "small" = "large"
param style: "solid" | "glass" | "outline" | "plain" = "solid"
param enabled: bool = true
event tap
let box = size == "small" ? 40 : 44
